import sys

def main():
    args = sys.argv[1:]
    flags = []
    filepath = None

    for arg in args:
        if arg.startswith('-'):
            for ch in arg[1:]:
                if ch in ('l', 'w', 'c'):
                    flags.append(ch)
        else:
            filepath = arg

    # If no flags specified, show all three
    if not flags:
        flags = ['l', 'w', 'c']

    # Read input
    if filepath is None or filepath == '-':
        data = sys.stdin.buffer.read()
    else:
        with open(filepath, 'rb') as f:
            data = f.read()

    # Count lines
    line_count = data.count(b'\n')
    # Final line without trailing newline still counts as a line
    if data and not data.endswith(b'\n'):
        line_count += 1

    # Count words (sequences of non-whitespace separated by whitespace)
    word_count = len(data.split())

    # Count characters (bytes)
    char_count = len(data)

    # Print in fixed order: l, w, c
    parts = []
    for flag in flags:
        if flag == 'l':
            parts.append(str(line_count))
        elif flag == 'w':
            parts.append(str(word_count))
        elif flag == 'c':
            parts.append(str(char_count))

    print(' '.join(parts))

if __name__ == '__main__':
    main()

